  /**
   * Draws the note shown when no LDAP directory is loaded in this process.
   *
   * @returns the note as HTML
   */
  noGroupDirectorySection() {
    const { log } = this.deps;
    log.debug("Entering AdminConsole.noGroupDirectorySection().");
    log.debug("Leaving AdminConsole.noGroupDirectorySection().");
    return this.note('No LDAP directory is loaded in this process, so there ' +
      'are no groups to show. That is a build of this service without ' +
      '<code>ldap_server.js</code> and not a failure &mdash; every other ' +
      'page of this console is unaffected.');
  }

  // The list.
  /**
   * Draws `/admin/groups`: every group in the directory, filtered and paged,
   * with the create form when this process has a group writer.
   *
   * @param req - the request, whose query carries the filter and paging
   * @returns the page body as HTML (`inner`) and its JSON view (`json`)
   */
  groupsListPage(req) {
    const { log, adminViews } = this.deps;
    log.debug("Entering AdminConsole.groupsListPage().");
    const json = adminViews.groupsListJson(req).json;
    // Drawn by `web_groups.ts` (#446).
    const inner = this.messagesOf(req) +
      GroupsPage.body(this.renderContext(req),
        JSON.parse(JSON.stringify(json)));
    log.debug("Leaving AdminConsole.groupsListPage(). " + json.shown + " " +
      "row(s) drawn of " + json.groupCount + " group(s).");
    return {
      inner: inner,
      json: json
    };
  }

  // One group: every attribute it has, and everybody in it.
  /**
   * Draws one group: its members, the entries that claim it back through
   * memberOf, the add-member form and every attribute it has.
   *
   * A DN that is gone or is not a group is answered with a note saying
   * which, not a 404.
   *
   * @param req - the request
   * @param wantedDn - the group's DN
   * @returns the page body as HTML (`inner`) and its JSON view (`json`)
   */
  groupDetailPage(req, wantedDn) {
    const { log, adminViews } = this.deps;
    log.debug("Entering AdminConsole.groupDetailPage(). dn=" + wantedDn);
    const json = adminViews.groupDetailJson(req, wantedDn).json;
    // Drawn by `web_groups.ts` (#446).
    const inner = this.messagesOf(req) +
      GroupsPage.detail(this.renderContext(req),
        JSON.parse(JSON.stringify(json)));
    log.debug("Leaving AdminConsole.groupDetailPage().");
    return {
      inner: inner,
      json: json
    };
  }

  /**
   * Chooses the groups list or one group's page from the query, or the
   * no-directory note when no group reader is installed.
   *
   * @param req - the request; `group` in its query names one group
   * @returns the view: `json`, `inner`, `title`, and `up` for a drill-down
   */
  groupsView(req) {
    const { log } = this.deps;
    log.debug("Entering AdminConsole.groupsView().");
    if (!groupReader) {
      // A build without ldap_server.js. Answered rather than 404'd, and with
      // the nav intact, for the same reason the user page's directory section
      // says it in words: the page exists, the directory does not, and those
      // are different facts about this process.
      log.debug("Leaving AdminConsole.groupsView(). No directory is loaded.");
      return { json: { directory: false, groups: [] }, title: 'Groups',
               inner: this.messagesOf(req) + this.noGroupDirectorySection() };
    }
    const wantedDn = String(req.query.group || '').trim();
    if (wantedDn) {
      const detail = this.groupDetailPage(req, wantedDn);
      log.debug("Leaving AdminConsole.groupsView(). The drill-down.");
      return { json: detail.json, inner: detail.inner,
               title: 'Group ' + wantedDn,
               // The whole DN is the leaf and shortCrumb() cuts it if it has
               // to, rather than being cut to its first RDN here: a leaf
               // trimmed at the shell keeps its full text in the tooltip, and a
               // DN cut here would lose the container it is in with nowhere
               // left to say so. What the cut drops is the tail, which is the
               // part every entry shares.
               up: this.upTo('/admin/groups', wantedDn,
                             this.listViewOf('/admin/groups', req.query)) };
    }
    const list = this.groupsListPage(req);
    log.debug("Leaving AdminConsole.groupsView(). The list.");
    return { json: list.json, inner: list.inner, title: 'Groups' };
  }

  // The kit's (#446), where its reasoning went with it.
