  // ---------------------------------------------------------------------------
  // WHERE A FORM POSTED FROM AN APPLICATION'S PAGE TO ANOTHER HANDLER GOES BACK
  // TO (2026-09-13). The Credentials section below draws `/admin/pki`'s issue,
  // upload and take-off controls, which post to that page's handler — moving a
  // FORM is not moving an ACTION — and that handler asks this for the way back.
  // Exported for `admin-ui/pki_admin.ts`; the destination is REBUILT from the
  // identifier and the list state `back` carries, never echoed, for
  // `permissionsReturnTo()`'s reason one section up.
  // ---------------------------------------------------------------------------
  /**
   * Rebuilds the path back to an application's page, with the list state
   * from `back`, for a form posted from it to another handler.
   *
   * @param body - the posted form body
   * @param identifier - the application's identifier
   * @param anchor - kept only when it is `#credentials`
   * @returns the path to redirect to
   */
  applicationReturnTo(body, identifier, anchor) {
    const { log, queryWith } = this.deps;
    log.debug("Entering AdminConsole.applicationReturnTo(). identifier=" +
              identifier);
    const listView = this.listViewFromBack('/admin/applications',
                                           body && body.back);
    log.debug("Leaving AdminConsole.applicationReturnTo().");
    return '/admin/applications' +
           queryWith(listView, { application: String(identifier) }) +
           (anchor === '#credentials' || anchor === '#fields' ||
            anchor === '#signals' ||
            /^#(?:tab|cfg|credentials)-[a-z0-9-]+$/.test(
              String(anchor || '')) ? anchor : '');
  }

  // And a PERSON's page (2026-09-13), whose Credentials section draws the same
  // `/admin/pki` controls for that person's RFC 7523 and RFC 7522 key pairs.
  // The same rule, the same shape: the name arrives in the body and the
  // destination is rebuilt around it, never echoed.
  /**
   * Rebuilds the path back to a person's page, with the list state from
   * `back`, for a form posted from it to another handler.
   *
   * @param body - the posted form body
   * @param key - the person's user key
   * @param anchor - kept only when it is one of the page's known sections
   * @returns the path to redirect to
   */
  userReturnTo(body, key, anchor) {
    const { log, queryWith } = this.deps;
    log.debug("Entering AdminConsole.userReturnTo(). key=" + key);
    const listView = this.listViewFromBack('/admin/users', body && body.back);
    log.debug("Leaving AdminConsole.userReturnTo().");
    // Each anchor is inside one tab of the person's page (2026-10-01), so
    // landing on it shows that tab.
    return '/admin/users' + queryWith(listView, { user: String(key) }) +
           (['#credentials', '#credential-controls', '#second-factors',
             '#attributes', '#mail', '#person-fields',
             '#federation-links'].indexOf(anchor) >= 0 ||
            /^#ufg-[a-z]+$/.test(String(anchor || ''))
             ? anchor : '');
  }

