    const { log } = this.deps;
    log.debug("Entering AdminConsole.applicationsView().");
    const wanted = String(req.query.application || '').trim();
    if (wanted) {
      const detail = this.applicationDetailPage(req, wanted);
      log.debug("Leaving AdminConsole.applicationsView(). The drill-down.");
      return { missing: !!detail.missing, json: detail.json,
               inner: detail.inner,
               title: 'Application ' + wanted,
               up: this.upTo('/admin/applications', wanted,
                             this.listViewOf('/admin/applications',
                                             req.query)) };
    }
    const list = this.applicationsListPage(req);
    log.debug("Leaving AdminConsole.applicationsView(). The list.");
    return { json: list.json, inner: list.inner, title: 'Applications' };
