  // ---------------------------------------------------------------------------
  // POST /admin/applications/new — THE RFC 9728 IMPORT'S TWO ROUND TRIPS.
  //
  // `load-resource-metadata` answers with this page and the pane on it;
  // `create` creates through the same `applicationsAction()` the list page
  // posts to, lands on the entry it made, and on a refusal redraws THIS page
  // with the document still loaded and every box as the reader left it. Any
  // other action is handed to that switch and answered as `/admin/applications`
  // answers it, so the unknown-action sentence a caller meets here is the same
  // one — which is the sentence the parity checks read.
  //
  // A JSON caller gets JSON throughout, as everywhere on this console.
  // ---------------------------------------------------------------------------
  /**
   * Answers with the new-application page redrawn from a round trip of its
   * own form, marking an error code when one is given.
   *
   * @param req - the request
   * @param res - the response
   * @param state - the page state to draw
   * @param code - optional; the error code to mark on the response
   */
  newApplicationRedraw(req, res, state, code?) {
    const { log, errorCodes } = this.deps;
    log.debug("Entering AdminConsole.newApplicationRedraw().");
    if (code) {
      errorCodes.mark(res, code);
    }
    const view = this.newApplicationView(req, state);
    this.respond(req, res, view.json, view.title, '/admin/applications',
                 view.inner,
                 this.upTo('/admin/applications', view.title));
    log.debug("Leaving AdminConsole.newApplicationRedraw().");
  }

