    // -------------------------------------------------------------------------
    // WHERE THE REALM CHOOSER SUBMITS.
    //
    // A `<select>` cannot navigate on its own without script, and this console
    // runs none (`script-src 'none'`, see common/app.js) — so the chooser is a
    // GET form and this is what it submits to. It exists only to turn a realm
    // id and a path into one redirect.
    //
    // **THE TARGET IS BUILT HERE AND NOT ECHOED.** `to` arrives in a query
    // string and ends up in a `Location` header, which is the shape of every
    // open-redirect there has ever been. So it is accepted only as a
    // single-slash-rooted path — `//host` and `https://host` and anything else
    // is refused rather than corrected — and the realm is looked up in the
    // registry rather than trusted, with `/admin` as the answer to both
    // refusals. What goes out is root + the chosen realm's prefix + a path this
    // service has vouched for.
    //
    // **THE REDIRECT IS ABSOLUTE, for the reason the form's action is.** app.js
    // wraps `res.location()` so that a root-relative target gains the CURRENT
    // realm's prefix — which is right for the six modules that send a browser
    // to the sign-in screen and exactly wrong here, where the whole point is to
    // land in a DIFFERENT realm. An absolute URL names a host, so that wrapper
    // passes it through.
    //
    // 303 rather than 302 so the reload after it is a GET, like every other
    // action on this console.
    // -------------------------------------------------------------------------
    app.get('/admin/realm-switch', function (req, res) {
      log.debug("Entering the admin realm switch endpoint.");
      const wanted = String(req.query.realm || '').trim();
      const target = realms.get(wanted);
      const asked = String(req.query.to || '');
      // A path this service is willing to put in a Location header: rooted, one
      // slash, no scheme, and short enough not to be a place to hide one.
      const path = (/^\/(?!\/)[^\s]*$/.test(asked) && asked.length <= 2000) ?
        asked : '/admin';
      if (asked && path !== asked) {
        errorCodes.mark(res, 'STS-ADMIN-0022');
      }
      if (!target) {
        log.debug("Leaving the admin realm switch endpoint. No such realm " +
          JSON.stringify(wanted) + ".");
        errorCodes.mark(res, 'STS-ADMIN-0020');
        res.set('Cache-Control', 'no-store')
           .redirect(303, self.realmRoot(req) + realms.currentPrefix() + path);
        return;
      }
      const to = self.realmRoot(req) + realms.prefixOf(target) + path;
      log.debug("Leaving the admin realm switch endpoint. To " + to + ".");
      res.set('Cache-Control', 'no-store').redirect(303, to);
    });

    app.get('/admin/realms', function (req, res, next) {
      log.debug("Entering the admin trust realms page.");
      // The list and the drill-down both show a realm's `kid`, which MAKES the
      // key set of a realm this process holds none for — made off the event
      // loop first, `GET /admin-api/realms`'s reason (#46). Never rejects.
      loadHelpers().prepareKeySets(realms.list().map(function (one) {
        return one.id;
      })).then(function () {
        const view = self.realmsView(req);
        if (view.missing) {
          errorCodes.mark(res, 'STS-ADMIN-0021');
        }
        self.respond(req, res, view.json, view.title, '/admin/realms',
                     view.inner,
                     view.up);
        log.debug("Leaving the admin trust realms page.");
      }).catch(function (e) {
        log.debug("Caught in the admin trust realms page: " +
                  ((e && e.message) || e));
        // Express 4 does not look at a returned promise; handed on, a throw is
        // the 500 it was before the page awaited anything.
        next(e);
      });
    });

    app.post('/admin/realms', function (req, res, next) {
      log.debug("Entering the admin trust realms action endpoint.");
      const body = parseBody(req);
      const answerRealmsAction = function (result) {
        log.debug("Entering answerRealmsAction().");
        const listView = self.listViewFromBack('/admin/realms', body.back);
        const id = String(body.id || '').trim();
        // Back to the realm that was acted on, EXCEPT after a removal —
        // there is nothing to drill into any more, and a 303 to a
        // drill-down for a realm that has just gone would answer with this
        // page's own "no such realm" message, which reads as a failure after
        // an action that succeeded.
        const back = (id && result.ok !== false &&
                      String(body.action) !== 'remove')
          ? '/admin/realms' + queryWith(listView, { realm: id })
          : '/admin/realms' + queryWith(listView, {});
        // A NEW REALM'S BOOTSTRAP PASSWORD, ONCE (2026-09-14, #32). Product
        // mode hands the realm's `admin` a generated password in the
        // create's result, and a redirect would put it in a query string; so
        // it is drawn on a page of its own, `/admin/users`' reset
        // arrangement. A JSON caller gets JSON.
        if (result.ok && result.password &&
            !/json/i.test(String(req.headers['content-type'] || ''))) {
          const made = realms.get(result.realm);
          const realmUrl = self.realmRoot(req) +
                           (made ? realms.prefixOf(made) : '') +
                           '/admin';
          self.respond(req, res, result, 'Realm created', '/admin/realms',
            '<h2>The "' + self.esc(result.realm) +
            '" realm\'s administrator, shown once</h2><table ' +
            'class="key"><tr><th>Username</th><td><code>' +
            self.esc(result.username) + '</code></td></tr></table>' +
            '<div class="secret">' + self.esc(result.password) + '</div>' +
            self.warn('<strong>Note it now.</strong> It is stored as a ' +
            'scrypt ' +
            'hash and cannot be shown again. It works once, at that realm\'s ' +
            'sign-in screen, where a new password must be chosen. This ' +
            'account ' +
            'administers the "' + self.esc(result.realm) +
            '" realm and nothing else.') +
            self.note('<a class="btn" href="' + self.esc(back) +
                      '">Back to the realm</a> ' +
            '&middot; <a href="' + self.esc(realmUrl) + '">its console</a>'),
            self.upTo('/admin/realms', 'Realm created', listView));
          log.debug("Leaving answerRealmsAction(). A one-time page.");
          return;
        }
        self.respondToAction(req, res, back, result);
        log.debug("Leaving answerRealmsAction().");
      };
      // A removal answers a promise (#232: the realm is retired first, which
      // waits a bounded time for what it owes to be delivered); every other
      // action answers at once. Both are resolved before the page answers.
      Promise.resolve(realmsAction(body)).then(function (result) {
        answerRealmsAction(result);
      }).catch(function (e) {
        log.debug("Caught in the admin trust realms action endpoint: " +
                  ((e && e.message) || e));
        next(e);
      });
      log.debug("Leaving the admin trust realms action endpoint.");
    });

    app.post('/admin/config', function (req, res) {
      log.debug("Entering the admin configuration action endpoint.");
      const body = parseBody(req);
      // A RESET ARRIVES AS `?reset=<key>` ON THE SECTION'S OWN FORM — see the
      // comment above the button in configRow() for why the key is in the URL.
      // It is normalised into the body here rather than in configAction(),
      // because this is the shape a BROWSER posts and that function is also
      // what the management API calls with an `action` taken from its own URL.
      const reset = String(req.query.reset || '').trim();
      // An ordered choice's checkboxes and numbers, folded into its one
      // value first (2026-10-01) — this is the shape a browser posts.
      const folded = reset ? null : self.foldOrderedChoices(body);
      const result = folded || configAction(reset
        ? { action: 'reset', key: reset, from: body.from }
        : body);
      // BACK TO THE PAGE THE FORM WAS ON. Every protocol page draws its own
      // settings and every one of those forms posts here, so this endpoint
      // serves twenty-one pages and can no longer assume it serves one. See
      // configReturnTo(), which is why an unrecognised `from` cannot become a
      // redirect to somewhere this file did not write.
      self.respondToAction(req, res, self.configReturnTo(body), result);
      log.debug("Leaving the admin configuration action endpoint.");
    });

